public class OrderApiClient
{
    private readonly HttpClient _http;
    private readonly TimeSpan _timeout = TimeSpan.FromSeconds(5);

    public OrderApiClient(HttpClient http)
    {
        _http = http;
        _http.Timeout = _timeout;
    }

    public async Task<OrderResult> GetOrderAsync(Guid id, CancellationToken ct)
    {
        var response = await _http.GetAsync($"/orders/{id}", ct);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<OrderResult>(cancellationToken: ct)
            ?? throw new InvalidOperationException("Empty response.");
    }
}

public static class ResiliencePolicies
{
    public static IAsyncPolicy<HttpResponseMessage> CreateHttpRetryPolicy()
    {
        return HttpPolicyExtensions
            .HandleTransientHttpError()
            .OrResult(msg => msg.StatusCode == System.Net.HttpStatusCode.NotFound)
            .WaitAndRetryAsync(
                retryCount: 3,
                sleepDurationProvider: attempt =>
                    TimeSpan.FromMilliseconds(200 * Math.Pow(2, attempt)),
                onRetry: (outcome, timespan, attempt, context) =>
                {
                    Console.WriteLine($"Retry {attempt} after {timespan.TotalMilliseconds}ms: " +
                        outcome.Exception?.Message ?? outcome.Result.StatusCode.ToString());
                    return Task.CompletedTask;
                }
            );
    }
}

[HttpGet("{id:guid}")]
public async Task<IActionResult> Get(Guid id, CancellationToken ct)
{
    var order = await _db.Orders
        .FirstOrDefaultAsync(o => o.Id == id, ct);

    if (order is null) return NotFound();

    var result = await _externalService.EnrichAsync(order, ct);
    return Ok(result);
}
